// The engine's API, typed from its OpenAPI document (api-types.ts, regenerated by `npm run api`).
// Every call gives {ok: true, data} or {ok: false, code, message, field?}; nothing is thrown.
import type { components, paths } from "./api-types";

export type Schemas = components["schemas"];
export type ApiError = { ok: false; code: string; message: string; field?: string };
export type Result<T> = { ok: true; data: T } | ApiError;

type Method = "get" | "put" | "post" | "delete";
type Json<R> = R extends { content: { "application/json": infer T } } ? T : never;
type Success<O> = O extends { responses: infer R }
  ? R extends { 200: infer A }
    ? Json<A>
    : R extends { 201: infer B }
      ? Json<B>
      : never
  : never;
type Body<O> = O extends { requestBody: { content: { "application/json": infer B } } } ? B : undefined;
type Operation<P extends keyof paths, M extends Method> = NonNullable<paths[P][M]>;

// The engine's error body ({"error": {"code", "message", "field"?}}), or FastAPI's own validation body.
type EngineError = { error?: { code?: unknown; message?: unknown; field?: unknown } };
type ValidationBody = { detail?: { loc?: unknown[]; msg?: unknown }[] | string };

export function errorFrom(status: number, body: unknown): ApiError {
  const engine = (body as EngineError | null)?.error;
  if (engine !== undefined && typeof engine.code === "string") {
    const error: ApiError = { ok: false, code: engine.code, message: String(engine.message ?? "") };
    if (typeof engine.field === "string") error.field = engine.field;
    return error;
  }
  const detail = (body as ValidationBody | null)?.detail;
  if (status === 422 && Array.isArray(detail)) {
    const problems = detail.map((problem) => {
      const loc = (problem.loc ?? []).slice(1).join(".");
      return loc === "" ? String(problem.msg) : `${loc}: ${String(problem.msg)}`;
    });
    const error: ApiError = { ok: false, code: "recipe-invalid", message: problems.join("; ") };
    const field = detail[0]?.loc?.[1];
    if (detail[0]?.loc?.[0] === "body" && field !== undefined) error.field = String(field);
    return error;
  }
  return { ok: false, code: "internal-error", message: `the engine answered ${status}` };
}

async function call<P extends keyof paths, M extends Method>(
  method: M,
  path: P,
  body?: Body<Operation<P, M>>,
  url: string = path,
  signal?: AbortSignal,
): Promise<Result<Success<Operation<P, M>>>> {
  const init: RequestInit = { method: method.toUpperCase(), headers: { Accept: "application/json" } };
  if (signal) init.signal = signal;
  if (body !== undefined) {
    init.body = JSON.stringify(body);
    init.headers = { ...init.headers, "Content-Type": "application/json" };
  }
  let response: Response;
  try {
    response = await fetch(url, init);
  } catch {
    if (signal?.aborted) return { ok: false, code: "paused", message: "Measurement cancelled" };
    return { ok: false, code: "engine-unreachable", message: "The engine did not answer." };
  }
  let data: unknown = null;
  try {
    data = await response.json();
  } catch {
    // a body that is not JSON: described by the status below
  }
  if (!response.ok) return errorFrom(response.status, data);
  if (signal?.aborted) return { ok: false, code: "paused", message: "Measurement cancelled" };
  return { ok: true, data: data as Success<Operation<P, M>> };
}

export const api = {
  motion: (id: string) => call("get", "/api/v1/clips/{clip_id}/motion", undefined, `/api/v1/clips/${encodeURIComponent(id)}/motion`),
  captureChecks: (id: string, signal?: AbortSignal) => call("get", "/api/v1/clips/{clip_id}/checks", undefined, `/api/v1/clips/${encodeURIComponent(id)}/checks`, signal),
  clipReport: (ids: string[], format: "csv" | "ale" | "gpx") => call("post", "/api/v1/clips/report", { ids, format }),
  openCaptureRecording: (path: string) => call("post", "/api/v1/camera-capture/recordings", { path }),
  captureProfiles: () => call("get", "/api/v1/camera-capture"),
  analyseCameraProfile: (request: Schemas["LensCaptureRequest"], signal?: AbortSignal) => call("post", "/api/v1/camera-capture/analyse", request, "/api/v1/camera-capture/analyse", signal),
  saveCaptureProfile: (profile: Schemas["CameraProfile"]) => call("post", "/api/v1/camera-capture", { profile }),
  deleteCameraProfile: (name: string) => call("delete", "/api/v1/camera-capture/{name}", undefined, `/api/v1/camera-capture/${encodeURIComponent(name)}`),
  cameraProfiles: () => call("get", "/api/v1/camera-profiles"),
  analyseLens: (path: string, model: "opencv_standard" | "opencv_fisheye", signal?: AbortSignal) => call("post", "/api/v1/camera-profiles/analyse", { path, model }, undefined, signal),
  saveCameraProfile: (profile: Schemas["CameraProfile"]) => call("post", "/api/v1/camera-profiles", { profile }),
  about: () => call("get", "/api/v1/about"),
  supportReport: () => call("post", "/api/v1/support/report"),
  licence: (file: string) => call("get", "/api/v1/about/licences/{file}", undefined, `/api/v1/about/licences/${encodeURIComponent(file)}`),
  session: () => call("get", "/api/v1/session"),
  updateSession: (workspace: Schemas["Workspace"]) => call("put", "/api/v1/session", workspace),
  newSession: () => call("post", "/api/v1/session/new"),
  loadSession: (path: string) => call("post", "/api/v1/session/load", { path }),
  saveSession: (path?: string, portable?: boolean) => call("post", "/api/v1/session/save", { path, portable }),
  unmountAll: () => call("post", "/api/v1/mounts/unmount-all"),
  scanCard: (sources: string[]) => call("post", "/api/v1/offload/scan", { sources }),
  startCopy: (request: Schemas["OffloadRequest"]) => call("post", "/api/v1/offload", request),
  copyStatus: () => call("get", "/api/v1/offload"),
  cancelCopy: () => call("post", "/api/v1/offload/cancel"),
  resetBackups: () => call("get", "/api/v1/reset-backups"),
  resetOptions: () => call("get", "/api/v1/reset-options"),
  resetScope: (scope: "defaults" | "preferences" | "workspace", version: string) => call("post", "/api/v1/reset", { scope, version }),
  restoreReset: (backup: string, version: string) => call("post", "/api/v1/reset/restore", { backup, version }),
  cacheUsage: () => call("get", "/api/v1/cache"),
  previewCacheUsage: () => call("get", "/api/v1/cache/preview"),
  clearPreviewCache: () => call("post", "/api/v1/cache/preview/clear"),
  clearCache: (kind: "analysis" | "optical-tracks" | "exposure") => call("post", "/api/v1/cache/clear", { kind }),
  adjustmentDefaults: () => call("get", "/api/v1/adjustment-defaults"),
  colour: () => call("get", "/api/v1/colour"),
  applyDefaults: (version: string, values: RecipeValues) => call("put", "/api/v1/adjustment-defaults", { version, values }),
  trashClips: (clip_ids: string[]) => call("post", "/api/v1/clips/trash", { clip_ids }),
  mounts: () => call("get", "/api/v1/mounts"),
  mount: (clip_id: string) => call("post", "/api/v1/mounts", { clip_id }),
  remount: (id: string) => call("post", "/api/v1/mounts/{mount_id}/remount", undefined, `/api/v1/mounts/${encodeURIComponent(id)}/remount`),
  unmount: (id: string) => call("post", "/api/v1/mounts/{mount_id}/unmount", undefined, `/api/v1/mounts/${encodeURIComponent(id)}/unmount`),
  vignetteProfile: (id: string) => call("get", "/api/v1/clips/{clip_id}/vignette-profile", undefined, `/api/v1/clips/${encodeURIComponent(id)}/vignette-profile`),
  clipTiming: (id: string, signal?: AbortSignal) => call("get", "/api/v1/clips/{clip_id}/timing", undefined, `/api/v1/clips/${encodeURIComponent(id)}/timing`, signal),
  sensorClipping: (id: string, recipe: RecipeValues, index: number, mode: "any" | "all", signal: AbortSignal) => call("post", "/api/v1/clips/{clip_id}/sensor-clipping", { recipe: recipe as Schemas["Recipe"], index, mode, width: 1280 }, `/api/v1/clips/${encodeURIComponent(id)}/sensor-clipping`, signal),
  keptFrame: (id: string, recipe: RecipeValues, quick: boolean, signal?: AbortSignal) => call("post", "/api/v1/clips/{clip_id}/kept-frame", { recipe: recipe as Schemas["Recipe"], quick }, `/api/v1/clips/${encodeURIComponent(id)}/kept-frame`, signal),
  previewOverlays: (id: string, recipe: RecipeValues, signal?: AbortSignal) => call("post", "/api/v1/clips/{clip_id}/preview-overlays", { recipe: recipe as Schemas["Recipe"] }, `/api/v1/clips/${encodeURIComponent(id)}/preview-overlays`, signal),
  shadingMap: (id: string, frame: number, signal?: AbortSignal) => call("get", "/api/v1/clips/{clip_id}/shading-map", undefined, `/api/v1/clips/${encodeURIComponent(id)}/shading-map?frame=${frame}`, signal),
  clipAnalytics: (id: string, signal?: AbortSignal, refresh = false) => call("get", "/api/v1/clips/{clip_id}/analytics-scan", undefined, `/api/v1/clips/${encodeURIComponent(id)}/analytics-scan${refresh ? "?refresh=true" : ""}`, signal),
  clipGyro: (id: string, signal?: AbortSignal) => call("get", "/api/v1/clips/{clip_id}/gyro", undefined, `/api/v1/clips/${encodeURIComponent(id)}/gyro`, signal),
  rawHistogram: (id: string, signal?: AbortSignal) => call("get", "/api/v1/clips/{clip_id}/raw-histogram", undefined, `/api/v1/clips/${encodeURIComponent(id)}/raw-histogram`, signal),
  saveVignetteProfile: (id: string, version: string, profile: Schemas["VignetteProfile"] | null) => call("put", "/api/v1/clips/{clip_id}/vignette-profile", { version, profile }, `/api/v1/clips/${encodeURIComponent(id)}/vignette-profile`),
  // gyro and rolling_shutter are ignored by the engine: each clip's Stabilise settings decide.
  // `progress` tags the send's stages on the event stream (`send` events, lib/events.ts).
  sendMountsToResolve: (mounts: string[], mode: "bin" | "timeline" = "bin", progress?: string) => call("post", "/api/v1/resolve/mounts/send", { mounts, mode, gyro: false, unchecked_gyro: false, rolling_shutter: false, progress }),
  // Each clip's rate as it would mount, before anything is mounted for a timeline.
  timelineRates: (clip_ids: string[]) => call("post", "/api/v1/resolve/timeline/rates", { clip_ids }),
  annotations: (id: string) => call("get", "/api/v1/clips/{clip_id}/annotations", undefined, `/api/v1/clips/${encodeURIComponent(id)}/annotations`),
  saveAnnotations: (id: string, version: string, values: Schemas["ClipAnnotations"]) => call("put", "/api/v1/clips/{clip_id}/annotations", { version, values }, `/api/v1/clips/${encodeURIComponent(id)}/annotations`),
  recipe: (id: string) => call("get", "/api/v1/clips/{clip_id}/recipe", undefined, `/api/v1/clips/${encodeURIComponent(id)}/recipe`),
  skim: (id: string) => call("get", "/api/v1/clips/{clip_id}/skim", undefined, `/api/v1/clips/${encodeURIComponent(id)}/skim`),
  waveform: (id: string) => call("get", "/api/v1/clips/{clip_id}/waveform", undefined, `/api/v1/clips/${encodeURIComponent(id)}/waveform`),
  health: () => call("get", "/api/v1/health"),
  doctor: () => call("get", "/api/v1/doctor"),
  settings: () => call("get", "/api/v1/settings"),
  library: () => call("get", "/api/v1/library"),
  openedClips: () => call("get", "/api/v1/opened-clips"),
  openClips: (paths: string[]) => call("post", "/api/v1/opened-clips", { paths }),
  clearOpenedClips: () => call("delete", "/api/v1/opened-clips"),
  removeOpenedClips: (paths: string[]) => call("post", "/api/v1/opened-clips/remove", { paths }),
  clip: (id: string) => call("get", "/api/v1/clips/{clip_id}", undefined, `/api/v1/clips/${encodeURIComponent(id)}`),
  pickWhiteBalance: (id: string, recipe: RecipeValues, index: number, rectangle: [number, number, number, number]) => call("post", "/api/v1/clips/{clip_id}/white-balance", { recipe, index, rectangle }, `/api/v1/clips/${encodeURIComponent(id)}/white-balance`),
  validateWhiteBalance: (id: string, recipe: RecipeValues) => call("post", "/api/v1/clips/{clip_id}/white-balance/validate", { recipe }, `/api/v1/clips/${encodeURIComponent(id)}/white-balance/validate`),
  saveSettings: (settings: Schemas["SettingsUpdate"]) => call("put", "/api/v1/settings", settings),
};

// Recipe routes expose open dictionaries; keep the editable shape explicit here.
export type RecipeValues = { [key: string]: unknown; develop?: Record<string, unknown>; motion?: Record<string, unknown>; output?: Record<string, unknown>; trim?: { start?: string | null; duration?: string | null } };
export type RecipeLayer = { version: string; values: RecipeValues };
export type ClipRecipe = { layer: RecipeLayer; resolved: RecipeValues; inherited?: RecipeValues; sources?: Record<string, string>; inherited_sources?: Record<string, string> };
export type AnalysisDocument = Schemas["AnalysisDocument"];
export const developApi = {
  recipe: async (id: string): Promise<Result<ClipRecipe>> =>
    call("get", "/api/v1/clips/{clip_id}/recipe", undefined, `/api/v1/clips/${encodeURIComponent(id)}/recipe`) as Promise<Result<ClipRecipe>>,
  save: async (id: string, layer: RecipeLayer): Promise<Result<RecipeLayer>> =>
    call("put", "/api/v1/clips/{clip_id}/recipe", { values: layer.values, version: layer.version }, `/api/v1/clips/${encodeURIComponent(id)}/recipe`) as Promise<Result<RecipeLayer>>,
  analysis: (id: string) => call("get", "/api/v1/clips/{clip_id}/analysis", undefined, `/api/v1/clips/${encodeURIComponent(id)}/analysis`),
};
